package com.nexushr.entity;
import jakarta.persistence.*; import java.time.*; import java.util.UUID;
@Entity @Table(name="attendance",uniqueConstraints=@UniqueConstraint(columnNames={"employee_id","work_date"})) public class Attendance { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(optional=false) private Employee employee; @Column(nullable=false) private LocalDate workDate; private LocalDateTime checkIn; private LocalDateTime checkOut; @Enumerated(EnumType.STRING) @Column(nullable=false) private AttendanceStatus status; private String notes; public UUID getId(){return id;} public Employee getEmployee(){return employee;} public void setEmployee(Employee v){employee=v;} public LocalDate getWorkDate(){return workDate;} public void setWorkDate(LocalDate v){workDate=v;} public LocalDateTime getCheckIn(){return checkIn;} public void setCheckIn(LocalDateTime v){checkIn=v;} public LocalDateTime getCheckOut(){return checkOut;} public void setCheckOut(LocalDateTime v){checkOut=v;} public AttendanceStatus getStatus(){return status;} public void setStatus(AttendanceStatus v){status=v;} public String getNotes(){return notes;} public void setNotes(String v){notes=v;} }
